// @pit: {"label": "Extract article details: moomoo premarket, CNBC AMD, ROST and INTU press releases"}
async ({ http: { request } }) => {
  const strip = (b: string) => String(b).replace(/<script[\s\S]*?<\/script>/g, "").replace(/<style[\s\S]*?<\/style>/g, "").replace(/<[^>]+>/g, " ").replace(/&#x27;|&#39;/g, "'").replace(/&amp;/g, "&").replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ");
  const H = { "User-Agent": "pinance research bot admin@example.com" };
  const jobs: [string, string, number][] = [
    ["https://www.moomoo.com/community/feed/qqq-gains-premarket-as-put-call-ratio-falls-close-to-117642511253510", "Pre-Market Outlook", 2500],
    ["https://www.cnbc.com/2026/11/19/amd-falls-on-short-seller-report-of-alleged-china-exposure.html", "short", 2500],
    ["https://www.sec.gov/Archives/edgar/data/745732/000074573226000047/q326exhibit991.htm", "", 2000],
    ["https://www.sec.gov/Archives/edgar/data/896878/000089687826000043/0000896878-26-000043-index.html", "", 1500],
  ];
  const r = await Promise.allSettled(jobs.map(([u]) => request(u, { maxBytes: 1500000, headers: H } as any)));
  return r.map((x: any, i) => {
    if (x.status !== "fulfilled") return String(x.reason).slice(0, 200);
    const t = strip(x.value.body); const k = jobs[i][1]; let idx = k ? t.indexOf(k) : 0;
    if (i === 1) { const m = t.search(/AMD shares|Advanced Micro Devices shares|short seller|short-seller report/i); idx = m > 0 ? m - 200 : 0; }
    if (i === 3) { const links = [...String(x.value.body).matchAll(/href="([^"]+\.htm)"/g)].map(m => m[1]); return links.join(" "); }
    return `${x.value.status} ` + t.slice(Math.max(0, idx), Math.max(0, idx) + jobs[i][2]);
  });
}
